<script lang="ts">
 import {onMount} from 'svelte';
 import {newBlock,normalizeDocument,blockLabels,type MailBlock,type MailDocument,type BlockKind} from '$lib/newsletter';
 import {editorPreview} from '$lib/newsletter/preview';
 import MailBlockProperties from './MailBlockProperties.svelte';
 import MailDialog from './MailDialog.svelte';
 let {doc=$bindable(),preheader='',assets,facility,disabled=false,onRefresh,onNotice,onSubject}:{doc:MailDocument;preheader?:string;assets:Record<string,any>[];facility:string;disabled?:boolean;onRefresh:()=>Promise<void>;onNotice:(message:string)=>void;onSubject:(subject:string)=>void}=$props();
 let panel=$state('content'),selected=$state(''),mobile=$state(false),history=$state<string[]>([]),future=$state<string[]>([]),dragId=$state(''),token=$state(''),height=$state(850),uploadBusy=$state(false);
 let iframe=$state<HTMLIFrameElement>();
 let canvas:HTMLDivElement;
 let canvasWidth=$state(660);
 let frameWidth=$derived(mobile?390:660),scale=$derived(Math.min(1,Math.max(240,canvasWidth-36)/frameWidth));
 let search=$state(''),saveKind=$state<'template'|'block'|null>(null),saveName=$state(''),savingAsset=$state(false),replaceTemplate=$state<MailDocument|null>(null);
 let aiPrompt=$state(''),aiKind=$state('body'),aiResult=$state(''),aiBusy=$state(false);
 let block=$derived(doc.blocks.find(b=>b.id===selected));
 let preview=$derived(editorPreview(doc,preheader,token));
 const icons:Record<BlockKind,string>={heading:'H',text:'T',richtext:'Aa',image:'▧',imageText:'▧ T',offer:'¥',callout:'▎',button:'↗',divider:'―',spacer:'↕',html:'</>'};
 onMount(()=>{token=crypto.randomUUID();const observer=new ResizeObserver(()=>canvasWidth=canvas.clientWidth);observer.observe(canvas);return()=>observer.disconnect();});
 function checkpoint(){if(disabled)return;const snapshot=JSON.stringify(doc);if(history.at(-1)!==snapshot)history=[...history.slice(-39),snapshot];future=[];}
 function canAppend(count=1){if(doc.blocks.length+count<=100)return true;onNotice('ブロックは100個以内で作成してください。');return false;}
 function add(kind:BlockKind){if(disabled||!canAppend())return;checkpoint();const next=newBlock(kind),at=doc.blocks.findIndex(b=>b.id===selected);doc.blocks.splice(at<0?doc.blocks.length:at+1,0,next);selected=next.id;}
 function undo(){if(!history.length)return;future=[...future,JSON.stringify(doc)];doc=JSON.parse(history.at(-1)!);history=history.slice(0,-1);}
 function redo(){if(!future.length)return;history=[...history,JSON.stringify(doc)];doc=JSON.parse(future.at(-1)!);future=future.slice(0,-1);}
 function move(id:string,offset:number){const i=doc.blocks.findIndex(b=>b.id===id),j=i+offset;if(i<0||j<0||j>=doc.blocks.length||disabled)return;checkpoint();const next=[...doc.blocks];[next[i],next[j]]=[next[j],next[i]];doc.blocks=next;}
 function drop(e:DragEvent,id:string){e.preventDefault();if(disabled||!dragId||dragId===id)return;const item=doc.blocks.find(b=>b.id===dragId);if(!item)return;checkpoint();const next=doc.blocks.filter(b=>b.id!==dragId);next.splice(next.findIndex(b=>b.id===id),0,item);doc.blocks=next;dragId='';}
 function duplicate(){if(!block||disabled||!canAppend())return;checkpoint();const next={...block,id:crypto.randomUUID(),label:block.label?block.label+'（コピー）':''};doc.blocks.splice(doc.blocks.findIndex(b=>b.id===selected)+1,0,next);selected=next.id;}
 function remove(){if(!block||disabled)return;checkpoint();const at=doc.blocks.findIndex(b=>b.id===selected);doc.blocks=doc.blocks.filter(b=>b.id!==selected);selected=doc.blocks[Math.min(at,doc.blocks.length-1)]?.id??'';}
 function patch(value:Partial<MailBlock>){if(block&&!disabled)Object.assign(block,value);}
 function highlight(){iframe?.contentWindow?.postMessage({type:'book-mail-highlight',token,id:selected},'*');}
 $effect(()=>{void selected;highlight();});
 function select(id:string,locate=false){selected=id;if(locate)iframe?.contentWindow?.postMessage({type:'book-mail-locate',token,id},'*');}
 function receive(event:MessageEvent){if(event.source!==iframe?.contentWindow||event.data?.token!==token)return;const value=event.data;if(value.type==='book-mail-select'&&doc.blocks.some(b=>b.id===value.id))selected=value.id;else if(value.type==='book-mail-height'&&Number.isFinite(value.height))height=Math.min(25000,Math.max(500,value.height));else if(value.type==='book-mail-position'&&Number.isFinite(value.top))canvas.scrollTo({top:value.top*scale+40,behavior:'smooth'});}
 async function api(action:string,data:unknown){const f=new FormData();f.set('facility',facility);f.set('action',action);f.set('data',JSON.stringify(data));const r=await fetch('/admin/mail/api',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.error??'保存できませんでした。');return j.data;}
 async function saveAsset(){if(!saveKind||!saveName.trim()||savingAsset)return;savingAsset=true;try{await api('asset',{kind:saveKind,name:saveName.trim(),document:saveKind==='block'?{...doc,blocks:block?[block]:[]}:doc});saveKind=null;saveName='';await onRefresh();onNotice('デザインを保存しました。');}catch(e){onNotice(String(e));}finally{savingAsset=false;}}
 function chooseImage(url:string,alt:string){if(disabled)return;checkpoint();if(block&&['image','imageText'].includes(block.kind)){block.url=url;block.alt=alt;}else{if(!canAppend())return;const next=newBlock('image');next.url=url;next.alt=alt;doc.blocks.push(next);selected=next.id;}}
 async function upload(files:File[],targetId?:string){if(disabled||uploadBusy)return;uploadBusy=true;try{for(const [i,file] of files.slice(0,10).entries()){const form=new FormData();form.set('file',file);form.set('facilityId',facility);const r=await fetch('/admin/mail/images',{method:'POST',body:form}),j=await r.json();if(!r.ok)throw Error(j.error??'アップロードできませんでした。');const target=doc.blocks.find(b=>b.id===targetId);if(target&&!disabled){checkpoint();target.url=j.url;}onNotice(`画像を保存しました（${i+1}/${Math.min(files.length,10)}）。`);}await onRefresh();}catch(e){onNotice(String(e));}finally{uploadBusy=false;}}
 async function generate(){if(aiBusy||disabled)return;aiBusy=true;aiResult='';try{const f=new FormData();f.set('facility',facility);f.set('kind',aiKind);f.set('prompt',aiPrompt);f.set('tone','丁寧で上品');const r=await fetch('/admin/mail/ai',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.message??j.error??'生成できませんでした。');if(j.url){chooseImage(j.url,aiPrompt.slice(0,200));await onRefresh();}else aiResult=j.text;}catch(e){onNotice(String(e));}finally{aiBusy=false;}}
 function adopt(){if(aiKind==='subject')onSubject(aiResult);else{if(!canAppend())return;checkpoint();const next=newBlock(aiKind==='cta'?'button':'text');next.text=aiResult;doc.blocks.push(next);selected=next.id;}aiResult='';}
 function applyTemplate(){if(!replaceTemplate)return;checkpoint();doc=normalizeDocument({...replaceTemplate,blocks:replaceTemplate.blocks.map(b=>({...b,id:crypto.randomUUID()}))});selected='';replaceTemplate=null;}
</script>
<svelte:window onmessage={receive}/>
<section class="designer" aria-label="メルマガデザインエディタ">
 <aside class="library">
  <nav aria-label="編集ツール">{#each [['content','＋','追加'],['layers','☷','構成'],['images','▧','画像'],['templates','▤','保存'],['ai','✧','AI'],['settings','◈','全体']] as [key,icon,label]}<button class:active={panel===key} onclick={()=>panel=key}><span aria-hidden="true">{icon}</span>{label}</button>{/each}</nav>
  <div class="library-body">
  {#if panel==='content'}<p class="section-label">コンテンツを追加</p><p class="hint mb-4">選択中のブロックの下に追加します。</p><div class="block-grid">{#each Object.entries(blockLabels) as [kind,label]}<button class="add-block" disabled={disabled} onclick={()=>add(kind as BlockKind)}><span>{icons[kind as BlockKind]}</span>{label}</button>{/each}</div>
  {:else if panel==='layers'}<p class="section-label">メールの構成 <span>{doc.blocks.length}</span></p><p class="hint mb-4">ドラッグまたは上下ボタンで並べ替え。</p>{#each doc.blocks as b,i (b.id)}<div class="layer" class:chosen={selected===b.id} draggable={!disabled} ondragstart={()=>dragId=b.id} ondragend={()=>dragId=''} ondragover={e=>e.preventDefault()} ondrop={e=>drop(e,b.id)} role="group" aria-label={'ブロック '+(i+1)}><button class="layer-name" onclick={()=>select(b.id,true)}><span>{i+1}. {blockLabels[b.kind]}</span><strong>{b.label||b.heading||b.text.replace(/<[^>]*>/g,'').slice(0,28)||b.alt||'内容未設定'}</strong></button><div><button aria-label={'ブロック'+(i+1)+'を上へ'} disabled={disabled||i===0} onclick={()=>move(b.id,-1)}>↑</button><button aria-label={'ブロック'+(i+1)+'を下へ'} disabled={disabled||i===doc.blocks.length-1} onclick={()=>move(b.id,1)}>↓</button></div></div>{/each}
  {:else if panel==='images'}<p class="section-label">画像ライブラリ</p><label class="upload-box">＋ 画像をアップロード<input aria-label="画像ライブラリに追加" type="file" multiple accept="image/png,image/jpeg,image/webp,image/avif" disabled={disabled||uploadBusy} onchange={e=>void upload(Array.from(e.currentTarget.files??[]))}/></label><p class="hint my-3">1回10枚まで。画像を選ぶと、選択中の画像ブロックに反映します。</p><input class="search" aria-label="画像を検索" bind:value={search} placeholder="画像を検索"/><div class="image-grid">{#each assets.filter(a=>a.kind==='image'&&a.name.toLowerCase().includes(search.toLowerCase())) as asset}<button disabled={disabled} onclick={()=>chooseImage(asset.document.url,asset.document.alt??asset.name)}><img src={asset.document.url} alt={asset.document.alt??asset.name} loading="lazy"/><span>{asset.name}</span></button>{:else}<p class="hint">画像はまだありません。</p>{/each}</div>
  {:else if panel==='templates'}<p class="section-label">保存したデザイン</p><button class="button w-full mb-4" disabled={disabled} onclick={()=>{saveKind='template';saveName='';}}>現在のデザインを保存</button>{#each assets.filter(a=>['block','template'].includes(a.kind)) as asset}<button class="asset" disabled={disabled} onclick={()=>{if(asset.kind==='template')replaceTemplate=asset.document;else{if(!canAppend(asset.document.blocks.length))return;checkpoint();doc.blocks.push(...asset.document.blocks.map((b:MailBlock)=>({...b,id:crypto.randomUUID()})));}}}><span>{asset.kind==='template'?'テンプレート':'保存ブロック'}</span><strong>{asset.name}</strong></button>{/each}
  {:else if panel==='ai'}<p class="section-label">AIアシスタント</p><label>作成するもの<select bind:value={aiKind}><option value="body">本文</option><option value="subject">件名</option><option value="cta">ボタンの文言</option><option value="image">画像</option></select></label><label>内容・条件<textarea rows="7" bind:value={aiPrompt} maxlength="2048" placeholder="含めたい事実や、写真のイメージを入力"></textarea></label><button class="button primary w-full" disabled={disabled||aiBusy||!aiPrompt.trim()} onclick={()=>void generate()}>{aiBusy?'生成中…':'案を生成'}</button><p class="hint mt-3">1日あたり文章100回・画像20回。事実と表現を確認して採用してください。</p>{#if aiResult}<textarea aria-label="AIの提案" rows="9" bind:value={aiResult}></textarea><button class="button mt-3" disabled={disabled} onclick={adopt}>この案を採用</button>{/if}
  {:else}<p class="section-label">メール全体</p><label>背景色<input type="color" value={doc.background} disabled={disabled} onfocus={checkpoint} oninput={e=>doc.background=e.currentTarget.value}/></label><label>ブランドカラー<input type="color" value={doc.accent} disabled={disabled} onfocus={checkpoint} oninput={e=>doc.accent=e.currentTarget.value}/></label><details class="mt-6"><summary>差し込み項目</summary><p class="hint mt-3">件名・本文に入力できます。<br/><code>{'{{name|お客様}}'}</code><br/><code>{'{{email}}'}</code><br/><code>{'{{field:都道府県|ご住所}}'}</code><br/>「|」以降は、値が空の場合の表示です。</p></details>{/if}
  </div>
 </aside>
 <div class="workspace">
  <div class="canvas-toolbar"><div class="history"><button aria-label="元に戻す" title="元に戻す" disabled={disabled||!history.length} onclick={undo}>↶</button><button aria-label="やり直す" title="やり直す" disabled={disabled||!future.length} onclick={redo}>↷</button></div><div class="device"><button class:active={!mobile} onclick={()=>mobile=false}>PC</button><button class:active={mobile} onclick={()=>mobile=true}>モバイル</button></div><span class="width-hint">{mobile?'390':'600'}px</span></div>
  <div class="canvas-scroll" bind:this={canvas}><p class="canvas-tip">編集したい箇所をクリックしてください</p><div class="email-canvas" style:width={frameWidth*scale+'px'} style:height={height*scale+'px'}>{#key preview+frameWidth}<iframe bind:this={iframe} title="メールプレビュー・クリックで編集" sandbox="allow-scripts" referrerpolicy="no-referrer" srcdoc={preview} style:width={frameWidth+'px'} style:height={height+'px'} style:transform={'scale('+scale+')'} onload={highlight}></iframe>{/key}</div><div class="end-note">メール本文の終わり<span>配信時に送信者情報・配信停止リンクが追加されます</span></div></div>
 </div>
 <aside class="inspector" aria-label="選択ブロックの設定">{#if block}{#key block.id}<MailBlockProperties {block} {disabled} onPatch={patch} onUpload={(file,id)=>void upload([file],id)} onDuplicate={duplicate} onDelete={remove} onSave={()=>{saveKind='block';saveName=block?.label??'';}} onCheckpoint={checkpoint}/>{/key}{:else}<div class="inspector-empty"><div class="pointer">↖</div><h2>クリックして編集</h2><p>プレビューの画像や文章を選ぶと、ここに設定が表示されます。</p><p>左の「追加」から、新しいブロックを追加できます。</p></div>{/if}</aside>
</section>
{#if saveKind}<MailDialog title="デザインを保存" onDismiss={()=>saveKind=null}><div class="dialog-body"><h2>{saveKind==='template'?'テンプレート':'ブロック'}を保存</h2><label>名前<input bind:value={saveName} maxlength="200"/></label><div class="flex justify-end gap-3"><button class="button" onclick={()=>saveKind=null}>キャンセル</button><button class="button primary" disabled={!saveName.trim()||savingAsset} onclick={()=>void saveAsset()}>{savingAsset?'保存中…':'保存する'}</button></div></div></MailDialog>{/if}
{#if replaceTemplate}<MailDialog title="テンプレートを使用" onDismiss={()=>replaceTemplate=null}><div class="dialog-body"><h2>このテンプレートを使用しますか？</h2><p>現在の本文を置き換えます。「元に戻す」で戻せます。</p><div class="flex justify-end gap-3"><button class="button" onclick={()=>replaceTemplate=null}>キャンセル</button><button class="button primary" onclick={applyTemplate}>置き換える</button></div></div></MailDialog>{/if}
<style>
 .designer{display:grid;grid-template-columns:240px minmax(360px,1fr) 340px;border:1px solid #dfd8ce;border-radius:14px;overflow:hidden;background:#fff;min-height:760px;box-shadow:0 4px 20px #29252406}.library{border-right:1px solid #e7e1d8;background:#fff;min-width:0}.library nav{display:grid;grid-template-columns:repeat(3,1fr);padding:8px;gap:4px;border-bottom:1px solid #e7e1d8}.library nav button{display:flex;flex-direction:column;align-items:center;gap:3px;padding:9px 3px;font-size:14px;border-radius:7px;color:#78716c}.library nav button span{font-size:19px;line-height:24px}.library nav button.active{background:#f2eae1;color:#713e2e;font-weight:600}.library-body{padding:18px;max-height:calc(100vh - 310px);min-height:560px;overflow:auto}.section-label{font-size:15px;font-weight:650;display:flex;justify-content:space-between;margin-bottom:12px}.hint{font-size:14px;line-height:1.7;color:#78716c}.block-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.add-block{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;min-height:88px;padding:12px 4px;border:1px solid #e4ded5;border-radius:9px;font-size:14px;color:#57534e;background:#fff}.add-block span{font-size:23px;color:#8b633d;font-weight:500}.add-block:hover,.asset:hover{border-color:#b28a4c;background:#fdfaf4}.layer{border:1px solid #e7e1d8;border-radius:8px;margin-bottom:8px;display:flex;align-items:center;background:white}.layer.chosen{border-color:#8b282e;background:#fff9f6}.layer-name{min-width:0;flex:1;text-align:left;padding:12px}.layer-name span{display:block;font-size:14px;color:#8b633d}.layer-name strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:14px;font-weight:500;margin-top:5px}.layer>div button{display:block;padding:4px 9px;font-size:14px}.workspace{background:#eeeae4;min-width:0;position:relative}.canvas-toolbar{height:62px;display:flex;align-items:center;justify-content:space-between;padding:10px 20px;border-bottom:1px solid #dfd8ce;background:#faf8f5;gap:8px}.history{display:flex;gap:5px}.history button{width:36px;height:36px;border:1px solid #ddd6cb;border-radius:7px;background:white;font-size:22px;line-height:1}.device{display:flex;padding:3px;border:1px solid #ddd6cb;border-radius:8px;background:#ede8df;gap:3px}.device button{font-size:14px;padding:6px 12px;border-radius:5px;color:#78716c}.device .active{background:#fff;color:#292524;box-shadow:0 1px 3px #0001}.width-hint{font-size:14px;color:#a8a29e}.canvas-scroll{height:calc(100vh - 370px);min-height:660px;overflow:auto;padding:16px 18px 32px;position:relative;scrollbar-gutter:stable}.canvas-tip{text-align:center;font-size:14px;color:#8c8173;margin-bottom:14px}.email-canvas{margin:0 auto;background:#fff;box-shadow:0 8px 30px #3a2c2018;position:relative;line-height:0}.email-canvas iframe{position:absolute;left:0;top:0;transform-origin:top left;border:0;display:block;background:white;min-height:500px}.end-note{padding:25px 0 0;text-align:center;font-size:14px;color:#968b7d;line-height:1.8}.end-note span{display:block}.inspector{min-width:0;overflow:auto;max-height:calc(100vh - 310px);min-height:760px;border-left:1px solid #e7e1d8;background:#fff}.inspector-empty{padding:70px 28px;text-align:center;color:#8a8178;font-size:14px;line-height:1.8}.inspector-empty h2{font-size:18px;color:#57534e;margin-bottom:12px}.inspector-empty p{margin-bottom:16px}.pointer{font-size:36px;color:#b28a4c;margin-bottom:20px}.upload-box{display:block;border:1px dashed #bca68c;background:#fcfaf6;border-radius:8px;padding:14px;font-size:14px;color:#795637}.upload-box input{font-size:14px;max-width:100%;margin-top:12px}.search,input:not([type=file]),textarea,select{width:100%;min-height:42px;border:1px solid #d9d3ca;border-radius:7px;background:white;padding:10px;font-size:14px;margin-top:7px}label{font-size:14px;display:block;margin-bottom:16px}input[type=color]{padding:4px;height:42px}.image-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:15px}.image-grid button{text-align:left;border:1px solid #e7e1d8;border-radius:8px;overflow:hidden;background:#faf8f5;min-width:0}.image-grid img{width:100%;height:80px;object-fit:cover}.image-grid span{display:block;font-size:14px;padding:7px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.asset{display:block;width:100%;padding:14px;border:1px solid #e7e1d8;border-radius:8px;margin-bottom:10px;text-align:left}.asset span{display:block;color:#a08c71;font-size:14px;margin-bottom:5px}.asset strong{font-size:14px;font-weight:500}.button{min-height:42px;border:1px solid #d8cfc2;border-radius:7px;padding:9px 13px;font-size:14px;background:white}.primary{background:#773d32;color:white;border-color:#773d32}button:disabled{opacity:.4;cursor:default}.dialog-body{padding:28px;display:flex;flex-direction:column;gap:20px;font-size:14px}.dialog-body h2{font-size:20px;font-weight:600}summary{cursor:pointer;font-size:14px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #b28a4c;outline-offset:2px}@media(max-width:1500px){.designer{grid-template-columns:205px minmax(320px,1fr) 300px}.library-body{padding:12px}.canvas-scroll{padding:14px 10px}}@media(max-width:1150px){.designer{grid-template-columns:190px minmax(0,1fr)}.inspector{grid-column:1/-1;max-height:none;min-height:0;border-left:0;border-top:1px solid #e7e1d8}.inspector-empty{padding:24px}.canvas-scroll{min-height:600px}.library-body{min-height:600px}}@media(max-width:750px){.designer{grid-template-columns:1fr}.library{border-right:0}.library nav{grid-template-columns:repeat(6,1fr)}.library-body{max-height:270px;min-height:0}.block-grid{grid-template-columns:repeat(3,1fr)}.add-block{min-height:74px}.canvas-scroll{height:620px;min-height:0}.inspector{grid-column:auto}.designer{min-height:0}.image-grid{grid-template-columns:repeat(4,1fr)}}
</style>
